10	 * 所有加锁/增减方法必须在事务内调用，依赖 SELECT ... FOR UPDATE 行锁与
11	 * CHECK (used_* &gt;= 0) 约束保证并发下不超卖、不变负。
12	 */
13	@Repository
14	public class LedgerRepository {
15	
16	    private final JdbcTemplate jdbc;
17	
18	    public LedgerRepository(JdbcTemplate jdbc) {
19	        this.jdbc = jdbc;
20	    }
21	
22	    /** 公告当日已占用额度；账目行不存在视为 0。 */
23	    public int getUsedTotal(String campaignId, LocalDate utcDate) {
24	        Integer value = jdbc.query("SELECT used_total FROM quota_total_ledger "
25	                + "WHERE campaign_id = ? AND utc_date = ?",
26	                rs -> rs.next() ? rs.getInt(1) : null, campaignId, java.sql.Date.valueOf(utcDate));
27	        return value == null ? 0 : value;
28	    }
29	
30	    /** 访客当日已占用额度；账目行不存在视为 0。 */
31	    public int getUsedVisitor(String campaignId, String visitorId, LocalDate utcDate) {
32	        Integer value = jdbc.query("SELECT used_visitor FROM quota_visitor_ledger "
33	                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?",
34	                rs -> rs.next() ? rs.getInt(1) : null,
35	                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
36	        return value == null ? 0 : value;
37	    }
38	
39	    /** 确保公告当日账目行存在（不存在则以 0 创建）。 */
40	    public void ensureTotalRow(String campaignId, LocalDate utcDate) {
41	        jdbc.update("INSERT INTO quota_total_ledger (campaign_id, utc_date, used_total) "
42	                        + "SELECT ?, ?, 0 WHERE NOT EXISTS ("
43	                        + "SELECT 1 FROM quota_total_ledger WHERE campaign_id = ? AND utc_date = ?)",
44	                campaignId, java.sql.Date.valueOf(utcDate),
45	                campaignId, java.sql.Date.valueOf(utcDate));
46	    }
47	
48	    /** 确保访客当日账目行存在（不存在则以 0 创建）。 */
49	    public void ensureVisitorRow(String campaignId, String visitorId, LocalDate utcDate) {
50	        jdbc.update("INSERT INTO quota_visitor_ledger (campaign_id, visitor_id, utc_date, used_visitor) "
51	                        + "SELECT ?, ?, ?, 0 WHERE NOT EXISTS ("
52	                        + "SELECT 1 FROM quota_visitor_ledger "
53	                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?)",
54	                campaignId, visitorId, java.sql.Date.valueOf(utcDate),
55	                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
56	    }
57	
58	    /** 行锁读取公告当日已占用额度；账目行不存在视为 0。 */
59	    public int lockUsedTotal(String campaignId, LocalDate utcDate) {
60	        Integer value = jdbc.query("SELECT used_total FROM quota_total_ledger "
61	                        + "WHERE campaign_id = ? AND utc_date = ? FOR UPDATE",
62	                rs -> rs.next() ? rs.getInt(1) : null, campaignId, java.sql.Date.valueOf(utcDate));
63	        return value == null ? 0 : value;
64	    }
65	
66	    /** 行锁读取访客当日已占用额度；账目行不存在视为 0。 */
67	    public int lockUsedVisitor(String campaignId, String visitorId, LocalDate utcDate) {
68	        Integer value = jdbc.query("SELECT used_visitor FROM quota_visitor_ledger "
69	                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ? FOR UPDATE",
70	                rs -> rs.next() ? rs.getInt(1) : null,
71	                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
72	        return value == null ? 0 : value;
73	    }
74	
75	    /**
76	     * 条件占用一次公告当日额度：仅当占用后不超过 cap 时才 +1。
77	     *
78	     * @return 是否占用成功；false 表示总额度已满
79	     */
80	    public boolean tryIncrementTotal(String campaignId, LocalDate utcDate, int cap) {
81	        int rows = jdbc.update("UPDATE quota_total_ledger SET used_total = used_total + 1 "
82	                        + "WHERE campaign_id = ? AND utc_date = ? AND used_total + 1 <= ?",
83	                campaignId, java.sql.Date.valueOf(utcDate), cap);
84	        return rows == 1;
85	    }
86	
87	    /**
88	     * 条件占用一次访客当日额度：仅当占用后不超过 cap 时才 +1。
89	     *
90	     * @return 是否占用成功；false 表示访客额度已满
91	     */
92	    public boolean tryIncrementVisitor(String campaignId, String visitorId, LocalDate utcDate, int cap) {
93	        int rows = jdbc.update("UPDATE quota_visitor_ledger SET used_visitor = used_visitor + 1 "
94	                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ? AND used_visitor + 1 <= ?",
95	                campaignId, visitorId, java.sql.Date.valueOf(utcDate), cap);
96	        return rows == 1;
97	    }
98	
99	    /**
100	     * 占用一次公告当日额度（+1）。调用方须已持行锁并完成容量校验。
101	     */
102	    public void addTotal(String campaignId, LocalDate utcDate, int delta) {
103	        int rows = jdbc.update("UPDATE quota_total_ledger SET used_total = used_total + ? "
104	                        + "WHERE campaign_id = ? AND utc_date = ?",
105	                delta, campaignId, java.sql.Date.valueOf(utcDate));
106	        if (rows != 1) {
107	            throw new IllegalStateException("total ledger row missing for " + campaignId + " " + utcDate);
108	        }
109	    }
