112	     * 占用一次访客当日额度（+1）。调用方须已持行锁并完成容量校验。
113	     */
114	    public void addVisitor(String campaignId, String visitorId, LocalDate utcDate, int delta) {
115	        int rows = jdbc.update("UPDATE quota_visitor_ledger SET used_visitor = used_visitor + ? "
116	                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?",
117	                delta, campaignId, visitorId, java.sql.Date.valueOf(utcDate));
118	        if (rows != 1) {
119	            throw new IllegalStateException("visitor ledger row missing for "
120	                    + campaignId + " " + visitorId + " " + utcDate);
121	        }
122	    }
123	
124	    /** 释放一次公告当日额度（-1）；CHECK 约束保证不变负。 */
125	    public void releaseTotal(String campaignId, LocalDate utcDate) {
126	        int rows = jdbc.update("UPDATE quota_total_ledger SET used_total = used_total - 1 "
127	                        + "WHERE campaign_id = ? AND utc_date = ?",
