136	        int rows = jdbc.update("UPDATE quota_visitor_ledger SET used_visitor = used_visitor - 1 "
137	                        + "WHERE campaign_id = ? AND visitor_id = ? AND utc_date = ?",
138	                campaignId, visitorId, java.sql.Date.valueOf(utcDate));
